    foreach (qq[i,j]) begin c++; if (c > 0) continue; c += 100; end
    if (n == 0)
      $write("qq[i,j]: n=%0d first=- last=-", n);
    else
      $write("qq[i,j]: n=%0d first=%0d,%0d last=%0d,%0d", n, fi, fj, li, lj);
    $display(" brk=%0d cont=%0d", b, c);
  endfunction
  initial run();
endmodule
